import React from 'react';
import InputMessage from './InputMessage.js';
import Message from './Message.js';
import Search from './Search.js';

const Chat = () => {
  return (
    <div className='chat'>
      <div className='infoBar'>
        <span className='userName'>Chatpartner</span>
        <Search/>
      </div>
      <Message/>
      <InputMessage/>
    </div>
  )
}

export default Chat
